/*!
 * Themeasy — Image Accordion
 *
 * Interactive controller for the Image Accordion widget. Handles click/tap,
 * hover and full keyboard navigation between panels, keeps ARIA state in sync
 * and exposes the active panel's CTA to keyboard users. It also publishes the
 * inner width of an open panel (--tms-image-accordion-open-width), so the text
 * an opening panel reveals is laid out at its final width from the first frame
 * and never re-wraps while the panel grows; without JS that text simply takes
 * the panel's width.
 *
 * - Single namespace: window.Themeasy.imageAccordion
 * - Vanilla JS (no jQuery dependency)
 * - Safe to re-init (guards per element; re-init resets bound flags)
 * - Auto-initializes on DOM ready
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}
  window.Themeasy.imageAccordion = window.Themeasy.imageAccordion || {}

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  // ------------------------------------------------------------------------
  // Image Accordion
  // ------------------------------------------------------------------------

  /**
   * Initialize Image Accordion instances inside the given root (or document).
   *
   * @param {ParentNode} [root] Root node to scan. Defaults to document.
   */
  window.Themeasy.imageAccordion.init = function (root) {
    // ------------------------------------------------------------------------
    // Selectors & constants.
    // ------------------------------------------------------------------------
    const SELECTOR_ROOT    = '.tms-image-accordion'
    const SELECTOR_ITEM    = '.tms-image-accordion__item'
    const SELECTOR_TRIGGER = '.tms-image-accordion__trigger'
    const SELECTOR_BUTTON  = '.tms-image-accordion__button'
    const SELECTOR_CONTENT = '.tms-image-accordion__content'
    const CLASS_ACTIVE     = 'tms-image-accordion__item--active'
    const CLASS_TOGGLED    = 'tms-image-accordion__item--toggled'
    const OPEN_WIDTH_VAR   = '--tms-image-accordion-open-width'
    const BOUND_FLAG       = 'tmsImageAccordionBound'

    const scope = root || document
    const accordions = scope.querySelectorAll(SELECTOR_ROOT)
    if (!accordions.length) return

    accordions.forEach(function (accordion) {
      if (accordion.dataset[BOUND_FLAG] === '1') return
      bindAccordion(accordion)
      accordion.dataset[BOUND_FLAG] = '1'
    })

    /**
     * Bind a single Image Accordion instance.
     *
     * @param {HTMLElement} accordion Wrapper element.
     */
    function bindAccordion(accordion) {
      const items = Array.prototype.slice.call(accordion.querySelectorAll(SELECTOR_ITEM))
      if (!items.length) return

      const trigger = (accordion.getAttribute('data-trigger') || 'click').toLowerCase()
      const initialActive = normalizeIndex(parseInt(accordion.getAttribute('data-active-index'), 10), items.length)
      let activeIndex = initialActive

      items.forEach(function (item, index) {
        const triggerEl = item.querySelector(SELECTOR_TRIGGER)
        const button = item.querySelector(SELECTOR_BUTTON)

        if (triggerEl) {
          triggerEl.addEventListener('click', function (event) {
            event.preventDefault()
            activate(index)
          })

          triggerEl.addEventListener('keydown', function (event) {
            handleKey(event, index)
          })

          if (trigger === 'hover') {
            item.addEventListener('mouseenter', function () {
              activate(index)
            })
          }
        }

        // Active panel CTA should be reachable via keyboard — collapsed ones stay out.
        if (button) {
          button.addEventListener('click', function (event) {
            event.stopPropagation()
          })
        }
      })

      // Sync CTA tabbability once on boot.
      syncButtonTabbability()

      // The open width follows the accordion's width (and the breakpoint's gap
      // and padding, which only change with it). A re-init replaces the old
      // observer, so a re-bound accordion never measures twice.
      syncOpenWidth()

      if (accordion._tmsImageAccordionObserver) {
        accordion._tmsImageAccordionObserver.disconnect()
        accordion._tmsImageAccordionObserver = null
      }

      if (typeof window.ResizeObserver === 'function') {
        accordion._tmsImageAccordionObserver = new window.ResizeObserver(syncOpenWidth)
        accordion._tmsImageAccordionObserver.observe(accordion)
      }

      /**
       * Publish the inner width of an open panel. Panels grow from a 0% basis,
       * so an open one takes its grow factor's share of the row (the whole
       * width in a column), less the panel border and the content padding.
       */
      function syncOpenWidth() {
        const content = items[0].querySelector(SELECTOR_CONTENT)
        if (!content) return

        const style = window.getComputedStyle(accordion)
        const itemStyle = window.getComputedStyle(items[0])
        const contentStyle = window.getComputedStyle(content)

        const inner = accordion.clientWidth - parseFloat(style.paddingLeft) - parseFloat(style.paddingRight)
        let panel = inner

        if (style.flexDirection.indexOf('row') === 0 && items.length > 1) {
          const gap = parseFloat(style.columnGap) || 0
          const open = readNumberVar(style, '--tms-image-accordion-active-flex', 4)
          const closed = readNumberVar(style, '--tms-image-accordion-collapsed-flex', 1)
          panel = (inner - gap * (items.length - 1)) * open / (open + closed * (items.length - 1))
        }

        const chrome = parseFloat(itemStyle.borderLeftWidth) + parseFloat(itemStyle.borderRightWidth) +
          parseFloat(contentStyle.paddingLeft) + parseFloat(contentStyle.paddingRight)

        const width = Math.floor(panel - chrome)
        if (!Number.isFinite(width) || width <= 0) return

        accordion.style.setProperty(OPEN_WIDTH_VAR, width + 'px')
      }

      /**
       * Activate the panel at the given index and sync ARIA + button tab order.
       * Both panels that change are marked toggled: the skins animate a swap
       * only there, so a page load plays nothing.
       *
       * @param {number} index Item index (0-based).
       */
      function activate(index) {
        if (index < 0 || index >= items.length) return
        if (index === activeIndex) return

        if (activeIndex >= 0 && items[activeIndex]) {
          items[activeIndex].classList.add(CLASS_TOGGLED)
          items[activeIndex].classList.remove(CLASS_ACTIVE)
          const prevTrigger = items[activeIndex].querySelector(SELECTOR_TRIGGER)
          if (prevTrigger) prevTrigger.setAttribute('aria-expanded', 'false')
        }

        activeIndex = index
        items[activeIndex].classList.add(CLASS_TOGGLED, CLASS_ACTIVE)

        const nextTrigger = items[activeIndex].querySelector(SELECTOR_TRIGGER)
        if (nextTrigger) nextTrigger.setAttribute('aria-expanded', 'true')

        syncButtonTabbability()
      }

      /**
       * Keep only the active panel's CTA button reachable by keyboard.
       */
      function syncButtonTabbability() {
        items.forEach(function (item, index) {
          const button = item.querySelector(SELECTOR_BUTTON)
          if (!button) return
          button.setAttribute('tabindex', index === activeIndex ? '0' : '-1')
        })
      }

      /**
       * Keyboard navigation: arrows move and activate, Home/End jump, Enter/Space activate.
       *
       * @param {KeyboardEvent} event Keyboard event.
       * @param {number} currentIndex Index of the panel that received the key.
       */
      function handleKey(event, currentIndex) {
        const key = event.key
        const horizontalKeys = [ 'ArrowLeft', 'ArrowRight' ]
        const verticalKeys   = [ 'ArrowUp', 'ArrowDown' ]
        const navKeys = horizontalKeys.concat(verticalKeys, [ 'Home', 'End' ])

        if (key === 'Enter' || key === ' ') {
          event.preventDefault()
          activate(currentIndex)
          return
        }

        if (navKeys.indexOf(key) === -1) return

        event.preventDefault()

        let nextIndex = currentIndex

        if (key === 'ArrowRight' || key === 'ArrowDown') {
          nextIndex = (currentIndex + 1) % items.length
        } else if (key === 'ArrowLeft' || key === 'ArrowUp') {
          nextIndex = (currentIndex - 1 + items.length) % items.length
        } else if (key === 'Home') {
          nextIndex = 0
        } else if (key === 'End') {
          nextIndex = items.length - 1
        }

        const nextTrigger = items[nextIndex] && items[nextIndex].querySelector(SELECTOR_TRIGGER)
        if (nextTrigger) nextTrigger.focus()

        activate(nextIndex)
      }
    }
  }

  /**
   * Clamp a 1-based active index into a 0-based position within range.
   *
   * @param {number} raw One-based index from markup (0 disables initial activation).
   * @param {number} total Number of panels.
   * @returns {number} Zero-based index, or -1 when none should be active.
   */
  function normalizeIndex(raw, total) {
    if (isNaN(raw) || raw <= 0) return -1
    return Math.min(raw - 1, total - 1)
  }

  /**
   * Read a unitless custom property from a computed style.
   *
   * @param {CSSStyleDeclaration} style Computed style of the element.
   * @param {string} name Custom property name.
   * @param {number} fallback Value when unset or not a number.
   * @returns {number}
   */
  function readNumberVar(style, name, fallback) {
    const value = parseFloat(style.getPropertyValue(name))
    return Number.isFinite(value) ? value : fallback
  }

  /**
   * Reset the bound flag so init() can re-attach after Elementor re-renders
   * the widget inside the preview iframe.
   *
   * @param {ParentNode} [root] Root node to scan. Defaults to document.
   */
  window.Themeasy.imageAccordion.reset = function (root) {
    const scope = root || document
    const instances = scope.querySelectorAll('.tms-image-accordion')
    instances.forEach(function (inst) {
      delete inst.dataset.tmsImageAccordionBound
    })
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector('.tms-image-accordion')) {
      window.Themeasy.imageAccordion.init()
    }
  }

  window.Themeasy.imageAccordion.boot = boot

  // Auto-initialize on DOM ready.
  onDomReady(function () {
    window.Themeasy.imageAccordion.boot()
  })

})(window, document)
